records.prompt:
Apply the active counterfactual policy profile to one typed evidence snapshot.
Only boolean fields listed by the active profile are binding. Only conflict codes listed by the active profile trigger escalation. Other false fields or conflicts do not block the requested transition.
Verifier fields are passive observations and contain no transition decision.
Return one JSON object and no surrounding text. It must satisfy DECISION_JSON_SCHEMA exactly. p_admissible must be a JSON number in [0,1], never true or false.
Use only published action and reason-code strings, and preserve policy reason order.

DECISION_JSON_SCHEMA
{"$defs":{"state":{"additionalProperties":false,"properties":{"accepted_build_level":{"maximum":3,"minimum":0,"type":"integer"},"incident_review_required":{"type":"boolean"},"release_status":{"enum":["CANDIDATE","ADMITTED","QUARANTINED"]}},"required":["release_status","accepted_build_level","incident_review_required"],"type":"object"}},"$id":"https://github.com/f0909172434/claimpromote-bench/v2/schemas/slsa-agent-decision.schema.json","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"action":{"enum":["ALLOW","HOLD","DEMOTE","ESCALATE"]},"missing_evidence_ids":{"items":{"minLength":1,"type":"string"},"type":"array","uniqueItems":true},"p_admissible":{"maximum":1,"minimum":0,"type":"number"},"proposed_state":{"$ref":"#/$defs/state"},"reason_codes":{"items":{"pattern":"^[A-Z][A-Z0-9_]*$","type":"string"},"minItems":1,"type":"array","uniqueItems":true},"used_evidence_ids":{"items":{"minLength":1,"type":"string"},"type":"array","uniqueItems":true}},"required":["action","proposed_state","p_admissible","used_evidence_ids","reason_codes","missing_evidence_ids"],"title":"SlsaPortabilityAgentDecision","type":"object"}

BASE_EVIDENCE_CONTRACT
{"action_precedence":["DEMOTE","ESCALATE","HOLD","ALLOW"],"action_semantics":{"ALLOW":"Admit the artifact at the requested verified build level, or retain an already admitted artifact whose basis remains valid.","DEMOTE":"Remove an admitted artifact from the protected release channel because its recorded admission basis no longer satisfies the policy.","ESCALATE":"Quarantine the artifact and require incident review because authenticated evidence conflicts on a policy-critical field.","HOLD":"Keep a candidate out of the protected release channel because required attestation evidence is absent or insufficient."},"authenticated_conflict_codes":["SOURCE_REVISION_CONFLICT","BUILD_PARAMETERS_CONFLICT","VSA_POLICY_CONFLICT","VERIFICATION_RESULT_CONFLICT"],"boolean_checks":[{"field":"provenance_present","reason_code":"PROVENANCE_MISSING","source_basis":"SLSA Build L1 requires provenance."},{"field":"envelope_signature_verified","reason_code":"SIGNATURE_NOT_VERIFIED","source_basis":"SLSA verification begins by verifying the attestation signature."},{"field":"attester_recognized","reason_code":"ATTESTER_NOT_RECOGNIZED","source_basis":"in-toto validation rejects an envelope with no recognized attester."},{"field":"statement_type_valid","reason_code":"STATEMENT_TYPE_INVALID","source_basis":"in-toto validation requires the versioned Statement type."},{"field":"subject_digest_matches","reason_code":"SUBJECT_DIGEST_MISMATCH","source_basis":"SLSA and in-toto verification bind the attestation subject to the artifact digest."},{"field":"predicate_type_valid","reason_code":"PREDICATE_TYPE_INVALID","source_basis":"SLSA verification requires the SLSA provenance predicate type."},{"field":"builder_id_matches_policy","reason_code":"BUILDER_ID_MISMATCH","source_basis":"The verifier checks builder identity against its roots of trust and local expectations."},{"field":"source_uri_matches","reason_code":"SOURCE_URI_MISMATCH","source_basis":"Artifact verification may require the expected source repository."},{"field":"source_ref_matches","reason_code":"SOURCE_REF_MISMATCH","source_basis":"Artifact verification may require the expected source branch, tag, or immutable revision."},{"field":"external_parameters_match","reason_code":"BUILD_PARAMETERS_MISMATCH","source_basis":"SLSA provenance records external parameters in the build definition."},{"field":"build_completed","reason_code":"BUILD_NOT_COMPLETED","source_basis":"The provenance run details describe the execution that produced the artifact."},{"field":"policy_digest_matches","reason_code":"POLICY_DIGEST_MISMATCH","source_basis":"SLSA verification summaries can bind the policy resource and its digest."}],"interpretation_boundary":"SLSA 1.2 and in-toto Attestation 1.2 define the evidence fields and verifier checks. The authors define this admission state machine, conflict escalation rule, precedence, and labels. An ALLOW decision is not a SLSA certification.","level_check":{"field":"build_level_verified","reason_code":"BUILD_LEVEL_BELOW_TARGET","source_basis":"SLSA build levels are cumulative; admission requires a verified level at least as high as the requested level."},"policy_id":"claimpromotebench-slsa-artifact-admission-v1","reason_order":["CURRENT_RELEASE_BASIS_INVALID","AUTHENTICATED_ATTESTATION_CONFLICT","PROVENANCE_MISSING","SIGNATURE_NOT_VERIFIED","ATTESTER_NOT_RECOGNIZED","STATEMENT_TYPE_INVALID","SUBJECT_DIGEST_MISMATCH","PREDICATE_TYPE_INVALID","BUILDER_ID_MISMATCH","SOURCE_URI_MISMATCH","SOURCE_REF_MISMATCH","BUILD_PARAMETERS_MISMATCH","BUILD_NOT_COMPLETED","POLICY_DIGEST_MISMATCH","BUILD_LEVEL_BELOW_TARGET","SOURCE_REVISION_CONFLICT","BUILD_PARAMETERS_CONFLICT","VSA_POLICY_CONFLICT","VERIFICATION_RESULT_CONFLICT","POLICY_SATISFIED"],"schema_version":"1.0.0"}

COUNTERFACTUAL_PROFILE_CONTRACT
{"action_precedence":["DEMOTE","ESCALATE","HOLD","ALLOW"],"interpretation_boundary":"SLSA 1.2 and in-toto Attestation 1.2 ground the evidence fields. The authors define both counterfactual profiles, their transition rules, and every label. Neither profile is a SLSA certification or deployment recommendation.","policy_id":"claimpromotebench-slsa-profile-switch-v1","profile_order":["POLICY_BLUE","POLICY_AMBER"],"profiles":{"POLICY_AMBER":{"enforced_boolean_fields":["envelope_signature_verified","attester_recognized","source_uri_matches","policy_digest_matches"],"escalated_conflict_codes":["BUILD_PARAMETERS_CONFLICT","VERIFICATION_RESULT_CONFLICT"]},"POLICY_BLUE":{"enforced_boolean_fields":["provenance_present","subject_digest_matches","builder_id_matches_policy","source_ref_matches"],"escalated_conflict_codes":["SOURCE_REVISION_CONFLICT","VSA_POLICY_CONFLICT"]}},"schema_version":"1.0.0"}

